import{_ as d,C as i,o as r,c as n,j as t,a as o,b as c,w as s,E as l,a3 as h,a2 as p}from"./chunks/framework.CWWEQfK7.js";const C=JSON.parse('{"title":"Configure the five modules by responsibility","description":"Configure the Core, API, Worker, MCP, and frontend by responsibility, then verify that the running processes connect correctly.","frontmatter":{"page_id":"configuration-services","description":"Configure the Core, API, Worker, MCP, and frontend by responsibility, then verify that the running processes connect correctly."},"headers":[],"relativePath":"en/configuration/services.md","filePath":"en/configuration/services.md","lastUpdated":1786627803000}'),u={name:"en/configuration/services.md"};function m(f,e,b,P,y,v){const a=i("Mermaid");return r(),n("div",null,[e[1]||(e[1]=t("h1",{id:"configure-the-five-modules-by-responsibility",tabindex:"-1"},[o("Configure the five modules by responsibility "),t("a",{class:"header-anchor",href:"#configure-the-five-modules-by-responsibility","aria-label":'Permalink to "Configure the five modules by responsibility"'},"​")],-1)),e[2]||(e[2]=t("p",null,"Ershu consists of five independent modules. They share data contracts, but not all five run as services: Core is a shared package, while the other four provide a process or a web interface.",-1)),(r(),c(h,null,{default:s(()=>[l(a,{id:"mermaid-6",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Browser%5B%22Browser%22%5D%20--%3E%20Frontend%5B%22Frontend%22%5D%0A%20%20Frontend%20--%3E%7C%22%2Fapi%2Fv1%22%7C%20API%5B%22API%22%5D%0A%20%20Client%5B%22MCP%20client%22%5D%20--%3E%7C%22%2Fmcp%2F%22%7C%20MCP%5B%22MCP%22%5D%0A%20%20API%20--%3E%20Core%5B%22Shared%20Core%20services%22%5D%0A%20%20MCP%20--%3E%20Core%0A%20%20Worker%5B%22Worker%22%5D%20--%3E%20Core%0A%20%20API%20--%3E%20PG%5B(PostgreSQL)%5D%0A%20%20Worker%20--%3E%20PG%0A%20%20MCP%20--%3E%20PG%0A%20%20API%20--%3E%20Milvus%5B(Milvus)%5D%0A%20%20Worker%20--%3E%20Milvus%0A%20%20MCP%20--%3E%20Milvus%0A%20%20API%20--%3E%7C%22enqueue%22%7C%20Queue%5B%22PostgreSQL%20run%20queue%22%5D%0A%20%20Queue%20--%3E%7C%22claim%22%7C%20Worker%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p('<p>The API, Worker, and MCP depend only on Core. The Worker and MCP do not call the API or each other directly. They coordinate through projects, queued work, and index state in PostgreSQL.</p><h2 id="responsibilities-and-process-boundaries" tabindex="-1">Responsibilities and process boundaries <a class="header-anchor" href="#responsibilities-and-process-boundaries" aria-label="Permalink to &quot;Responsibilities and process boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th><th>Quick-deployment entry</th><th>Default address</th><th>Observable readiness signal</th></tr></thead><tbody><tr><td>Core</td><td>Settings, data models, database migrations, permissions, repository access, and shared queries</td><td><code>ershu-migrate.service</code></td><td>None</td><td>The migration service completes successfully</td></tr><tr><td>API</td><td>Browser authentication, project and repository management, runs, documents, search, chat, and administration</td><td><code>ershu-api.service</code></td><td><code>127.0.0.1:8000</code></td><td><code>/health</code> returns <code>status: ok</code>; see the dependency check below</td></tr><tr><td>Worker</td><td>Claims jobs, prepares read-only workspaces, builds trees, code indexes, relationships, and search indexes, and generates documents</td><td><code>ershu-worker.service</code></td><td>No listening port</td><td>The process stays up and a queued run starts progressing</td></tr><tr><td>MCP</td><td>Exposes permission-scoped, read-only tools to development agents</td><td><code>ershu-mcp.service</code></td><td><code>127.0.0.1:8001/mcp/</code></td><td>An authenticated <code>get_server_info</code> call returns the version, build commit, and tool list</td></tr><tr><td>Frontend</td><td>Provides the browser UI and only uses published HTTP interfaces</td><td>Nginx serving the release archive</td><td><code>127.0.0.1:8080</code></td><td>Initial administrator setup or sign-in loads without persistent network errors</td></tr></tbody></table><p>The API repository also provides a separate <code>ershu-api-poller</code> process for repository schedules expressed as UTC cron rules. It is not part of the API web process and does not replace the Worker.</p><h2 id="keep-shared-values-aligned" tabindex="-1">Keep shared values aligned <a class="header-anchor" href="#keep-shared-values-aligned" aria-label="Permalink to &quot;Keep shared values aligned&quot;">​</a></h2><p>When modules run independently, each process reads its own environment. A combined deployment can use <code>ershu/.env.example</code> as the superset of backend settings, while each module ignores fields it does not recognize.</p><p>Do not let these values drift between processes:</p><ul><li>The API, Worker, and MCP must use the same PostgreSQL database so that they see the same projects and run queue.</li><li>When vector retrieval is enabled, the API, Worker, and MCP should use the same Milvus database.</li><li>The Worker&#39;s <code>ENCRYPTION_KEY</code> must match the API value that encrypted repository credentials and model secrets. MCP uses the same value when it reads protected credentials.</li><li>The API and MCP require strong values of at least 32 characters for <code>SECRET_KEY</code>, <code>ENCRYPTION_KEY</code>, and <code>MCP_KEY_PEPPER</code>. The three values must differ from one another, and both services should use the same set.</li><li>Model channels live in the database and are managed through the web administration area or API, not through <code>.env</code>.</li></ul><p>See the <a href="./environment-reference">environment reference</a> for every field, default, and range.</p><h2 id="place-repository-workspaces-deliberately" tabindex="-1">Place repository workspaces deliberately <a class="header-anchor" href="#place-repository-workspaces-deliberately" aria-label="Permalink to &quot;Place repository workspaces deliberately&quot;">​</a></h2><p>Remote Git repositories do not require a shared MCP and Worker cache. Each process can prepare its own read-only workspace from the registered remote URL, so <code>REPOSITORY_STORAGE_PATH</code> may point to a local cache on each host.</p><p>Local repositories are different. A registered path is not copied to another host. Both the Worker and MCP must be able to see the same path when both need it, and the path must be covered by <code>TRUSTED_LOCAL_PATHS</code>. Production must not use <code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code> to bypass that boundary.</p><h2 id="systemd-start-order" tabindex="-1">systemd start order <a class="header-anchor" href="#systemd-start-order" aria-label="Permalink to &quot;systemd start order&quot;">​</a></h2><p>After <code>systemctl start ershu.target</code>, the quick deployment starts services in this order:</p><ol><li>Start PostgreSQL, Redis, Milvus, and their supporting infrastructure.</li><li>Upgrade the database through the Core migration entry point.</li><li>Start the API and inspect <code>/api/v1/health/dependencies</code>. Both <code>database.ok</code> and <code>milvus.ok</code> should be <code>true</code>. Redis is not included in this check.</li><li>Start the Worker and confirm that it does not exit because of a key, database, or structured-parser self-check failure.</li><li>Start MCP and leave it ready for clients that need it.</li><li>Nginx serves the frontend separately. Poller starts only after scheduled repository checks are enabled.</li></ol><p>The API and MCP <code>/health</code> endpoints are liveness signals only. Prove MCP readiness with an authenticated <code>get_server_info</code> call. Prove Worker readiness by observing it claim and advance a run.</p><h2 id="route-reverse-proxy-traffic-separately" tabindex="-1">Route reverse-proxy traffic separately <a class="header-anchor" href="#route-reverse-proxy-traffic-separately" aria-label="Permalink to &quot;Route reverse-proxy traffic separately&quot;">​</a></h2><p>A production proxy should preserve the original path and send these prefixes to different processes:</p><table tabindex="0"><thead><tr><th>Path</th><th>Target</th></tr></thead><tbody><tr><td><code>/api/</code></td><td>API port <code>8000</code></td></tr><tr><td><code>/mcp/</code></td><td>MCP port <code>8001</code></td></tr></tbody></table><p>The frontend uses same-origin <code>/api/v1</code> by default. Do not send <code>/mcp/</code> to the API port. When the proxy terminates HTTPS, forward the effective Host and <code>X-Forwarded-Proto</code>, and set <code>FORWARDED_ALLOW_IPS</code> to the actual proxy source. Add the external host and origin to <code>MCP_ALLOWED_HOSTS</code> and <code>MCP_ALLOWED_ORIGINS</code> as well.</p>',20))])}const A=d(u,[["render",m]]);export{C as __pageData,A as default};
